dynamic _rt_capitalize(dynamic s) {
  final str = s as String;
  if (str.isEmpty) return str;
  return str[0].toUpperCase() + str.substring(1);
}

bool _rt_blank_q(dynamic s) =>
    s == null || (s is String && s.trim().isEmpty);

bool _rt_starts_with(dynamic s, dynamic prefix) =>
