bool _rt_ends_with(dynamic s, dynamic suffix) =>
    (s as String).endsWith(suffix as String);
bool _rt_includes(dynamic s, dynamic part) =>
    (s as String).contains(part as String);

dynamic _rt_replace(dynamic s, dynamic from, dynamic to) =>
    (s as String).replaceAll(from as Pattern, to as String);

dynamic _rt_replace_first(dynamic s, dynamic from, dynamic to) =>
    (s as String).replaceFirst(from as Pattern, to as String);

dynamic _rt_str(List<dynamic> xs) => xs.map(_rt_str1).join('');
String _rt_str1(dynamic x) {
  if (x == null) return '';
  if (x is String) return x;
  return _rt_pr_str(x);
}

dynamic _rt_pr_str(dynamic x) => _rt_pr_str1(x);

String _rt_pr_str1(dynamic x) {
  if (x == null) return 'nil';
  if (x is String) {
    final escaped = x
        .replaceAll('\\', '\\\\')
        .replaceAll('"', '\\"')
        .replaceAll('\n', '\\n');
    return '"$escaped"';
  }
  if (x is _Kw || x is _Sym) return x.toString();
  if (x is List) return '[${x.map(_rt_pr_str1).join(' ')}]';
  if (x is Set) return '#{${x.map(_rt_pr_str1).join(' ')}}';
  if (x is Map) {
    final parts = x.entries
        .map((e) => '${_rt_pr_str1(e.key)} ${_rt_pr_str1(e.value)}')
        .join(', ');
    return '{$parts}';
  }
  return x.toString();
}

dynamic _rt_print(List<dynamic> xs) {
  _rt_io.stdout.write(xs.map(_rt_str1).join(' '));
  return null;
}

dynamic _rt_println(List<dynamic> xs) {
