dynamic _rt_name(dynamic x) {
  if (x is _Kw) return x.name;
  if (x is _Sym) return x.name;
  if (x is String) return x;
  return x.toString();
}

dynamic _rt_namespace(dynamic x) {
  if (x is _Kw) return x.ns;
  if (x is _Sym) return x.ns;
  return null;
}

bool _rt_nil_q(dynamic x) => x == null;
bool _rt_some_q(dynamic x) => x != null;
bool _rt_true_q(dynamic x) => x == true;
bool _rt_false_q(dynamic x) => x == false;
bool _rt_number_q(dynamic x) => x is num;
bool _rt_integer_q(dynamic x) => x is int;
bool _rt_double_q(dynamic x) => x is double;
bool _rt_string_q(dynamic x) => x is String;
bool _rt_keyword_q(dynamic x) => x is _Kw;
bool _rt_symbol_q(dynamic x) => x is _Sym;
bool _rt_map_q(dynamic x) => x is Map;
bool _rt_vector_q(dynamic x) => x is List;
bool _rt_list_q(dynamic x) => x is List;
bool _rt_set_q(dynamic x) => x is Set;
bool _rt_fn_q(dynamic x) => x is Function;
