    x is List || x is Map || x is Set || x is String;
bool _rt_empty_coll_q(dynamic x) => _rt_count(x) == 0;
bool _rt_zero_q(dynamic x) => x == 0;
bool _rt_pos_q(dynamic x) => (x as num) > 0;
bool _rt_neg_q(dynamic x) => (x as num) < 0;
