bool _rt_odd_q(dynamic x) => (x as int) % 2 != 0;

dynamic _rt_inc(dynamic x) => (x as num) + 1;
dynamic _rt_dec(dynamic x) => (x as num) - 1;

dynamic _rt_add(List<dynamic> xs) {
  num out = 0;
  for (final x in xs) out += x as num;
  return out;
}

dynamic _rt_sub(List<dynamic> xs) {
  if (xs.length == 1) return -(xs[0] as num);
  num out = xs[0] as num;
  for (var i = 1; i < xs.length; i++) out -= xs[i] as num;
  return out;
}

dynamic _rt_mul(List<dynamic> xs) {
  num out = 1;
  for (final x in xs) out *= x as num;
  return out;
}

dynamic _rt_div(List<dynamic> xs) {
  if (xs.length == 1) return 1 / (xs[0] as num);
  num out = xs[0] as num;
  for (var i = 1; i < xs.length; i++) out /= xs[i] as num;
  return out;
}

dynamic _rt_add2(dynamic a, dynamic b) => (a as num) + (b as num);
dynamic _rt_sub2(dynamic a, dynamic b) => (a as num) - (b as num);
dynamic _rt_mul2(dynamic a, dynamic b) => (a as num) * (b as num);
dynamic _rt_div2(dynamic a, dynamic b) => (a as num) / (b as num);
bool _rt_eq2(dynamic a, dynamic b) => _rt_eq(a, b);
bool _rt_lt2(dynamic a, dynamic b) => a < b;
bool _rt_lte2(dynamic a, dynamic b) => a <= b;
bool _rt_gt2(dynamic a, dynamic b) => a > b;
bool _rt_gte2(dynamic a, dynamic b) => a >= b;

dynamic _rt_mod(dynamic a, dynamic b) {
  final r = (a as num) % (b as num);
  if (r != 0 && ((r < 0) != (b < 0))) return r + (b as num);
  return r;
}

dynamic _rt_quot(dynamic a, dynamic b) =>
    ((a as num) / (b as num)).truncate();
dynamic _rt_rem(dynamic a, dynamic b) => (a as num) % (b as num);
dynamic _rt_max(List<dynamic> xs) => xs.reduce((a, b) => a > b ? a : b);
dynamic _rt_min(List<dynamic> xs) => xs.reduce((a, b) => a < b ? a : b);
dynamic _rt_abs(dynamic x) => (x as num).abs();
dynamic _rt_rand([dynamic n = null]) =>
    n == null ? _rt_random.nextDouble() : _rt_random.nextDouble() * (n as num);

final _rt_random = _rt_math.Random();

